import {supportedImageFormats,textFormats,paperChoices} from './export-formats.js';
export function expandedOptions(id,{field,textField,selectField,pagesField},existing){
 const n=(label,name,value,min,max,help='')=>textField(label,name,String(value),help,`type="number" min="${min}" max="${max}" step="any"`);
 const color=(label,name,value)=>field(label,name,`<input type="color" id="${name}" name="${name}" value="${value}">`);
 const s=selectField,advanced=html=>'<details class="advanced-options"><summary>Advanced options</summary><div>'+html+'</div></details>';
 const dpi=()=>s('Render resolution','dpi',[['144','144 DPI · Balanced'],['72','72 DPI · Screen'],['96','96 DPI'],['120','120 DPI'],['150','150 DPI'],['200','200 DPI'],['216','216 DPI'],['300','300 DPI · Print'],['600','600 DPI · Capped for memory'],['custom','Custom DPI']]);
 const range=()=>s('Page selection','pagePreset',[['custom','All pages or custom range below'],['odd','Odd pages'],['even','Even pages'],['first','First page'],['last','Last page']])+pagesField();
 const papers=()=>s('Paper size','paper',paperChoices)+s('Orientation','orientation',[['auto','Automatic'],['portrait','Portrait'],['landscape','Landscape']])+n('Custom width (mm)','paperWidth',210,25,1000)+n('Custom height (mm)','paperHeight',297,25,1000);
 const cleanup=()=>s('Text cleanup','cleanup',[['paragraphs','Join wrapped lines'],['lines','Keep line breaks'],['raw',id.endsWith('-ocr')?'Keep raw spacing and breaks':'Keep detected spacing']]);
 const txtAdvanced=()=>s('Page headings','pageHeadings',[['no','Do not add headings'],['yes','Add page headings']])+s('Text encoding · TXT / CSV / Markdown','textEncoding',[['utf8','UTF-8'],['utf16','UTF-16 little endian with BOM']])+s('Line endings · TXT / CSV / Markdown','newline',[['lf','LF · Web / macOS / Linux'],['crlf','CRLF · Windows']])+s('UTF-8 byte-order mark','bom',[['no','No BOM'],['yes','Include BOM']]);
 let html=existing;
 if(id==='to-images')html=s('Image format','imageFormat',supportedImageFormats())+dpi()+range()+advanced(n('Custom DPI','customDpi',144,36,600)+n('Quality · JPG / WebP / AVIF (%)','quality',90,1,100)+s('Color mode','colorMode',[['color','Original colors'],['grayscale','Grayscale'],['bw','Black and white · Threshold']])+n('Black and white threshold','threshold',128,0,255)+s('Rotate rendered pages','renderRotation',[['0','No extra rotation'],['90','90° clockwise'],['180','180°'],['270','270° clockwise']])+s('Page background','backgroundMode',[['white','White'],['color','Choose a color'],['transparent','Transparent · PNG / WebP / SVG only']])+color('Background color','background','#ffffff')+n('Maximum long edge (px)','maxEdge',3500,256,6000,'Render is capped to 12 megapixels. DPI is a target; large pages may be reduced.')+s('Download packaging','packageMode',[['auto','One image, or ZIP for multiple pages'],['zip','Always download ZIP']])+s('Page filename pattern','pageNaming',[['page','Original name + page number'],['padded','Original name + zero-padded page number'],['number','Page number only']]))+'<p class="settings-help">TIFF, BMP and PPM are uncompressed and can be large. GIF has 256 colors. SVG contains a raster page image. ICO is a thumbnail. AVIF appears only when this browser can encode it.</p>';
 if(id==='compress')html=s('Compression preset','compression',[['balanced','Balanced · 120 DPI'],['tiny','Smallest · 72 DPI'],['small','Small · 90 DPI'],['detail','Detailed · 144 DPI'],['print','Print · 200 DPI'],['custom','Custom quality and resolution']])+range()+advanced(n('Custom resolution (DPI)','customDpi',120,36,300)+n('Custom JPEG quality (%)','quality',68,1,100)+s('Color mode','colorMode',[['color','Original colors'],['grayscale','Grayscale'],['bw','Black and white']])+n('Black and white threshold','threshold',128,0,255));
 if(id==='grayscale')html=dpi()+range()+advanced(n('Custom DPI','customDpi',144,36,600)+s('Monochrome style','colorMode',[['grayscale','Continuous grayscale'],['bw','Black and white threshold']])+n('Threshold','threshold',128,0,255)+n('JPEG quality (%)','quality',90,1,100));
 if(id==='images')html=s('Page size','paper',[['fit','Fit each image'],...paperChoices])+s('Orientation','orientation',[['auto','Automatic'],['portrait','Portrait'],['landscape','Landscape']])+n('Page margin (pt)','margin',24,0,144)+s('Image placement','fitMode',[['contain','Fit inside page'],['cover','Fill page · May crop image'],['stretch','Stretch to fill · May distort']])+advanced(n('Custom page width (mm)','paperWidth',210,25,1000)+n('Custom page height (mm)','paperHeight',297,25,1000)+s('Image encoding','embedFormat',[['jpg','JPEG · Compact'],['png','PNG · Lossless']])+n('JPEG quality (%)','quality',92,1,100)+color('Page background','background','#ffffff')+n('Image DPI · Fit each image mode','imageDpi',96,36,600)+s('Output documents','imagePackaging',[['combined','One combined PDF'],['each','Separate PDF per image · ZIP']]));
 if(id==='merge')html=s('Document order','mergeOrder',[['manual','Use the order shown'],['name','Filename A–Z'],['reverse-name','Filename Z–A']])+s('Pages from each document','mergePages',[['all','All pages'],['odd','Odd pages'],['even','Even pages']])+s('Between documents','mergeSeparator',[['none','No separator'],['blank','Insert one blank page']]);
 if(id==='split')html=s('Split method','splitMode',[['each','One PDF per page'],['ranges','Custom ranges'],['every','Every N pages'],['odd-even','Odd and even page groups']])+n('Pages per part · Every N mode','splitEvery',2,1,200)+field('Custom ranges · One output per line','ranges','<textarea id="ranges" name="ranges" placeholder="1-3\n4-6"></textarea>')+s('Download packaging','packageMode',[['auto','PDF for one part; ZIP for multiple'],['zip','Always ZIP']]);
 if(id==='rotate')html=s('Rotation','angle',[['90','90° clockwise'],['180','180°'],['270','90° counterclockwise'],['0','0° · Reset in absolute mode']])+s('Apply rotation','rotationMode',[['relative','Add to existing rotation'],['absolute','Set absolute page rotation']])+range();
 if(id==='organize')html=s('Page order','orderMode',[['custom','Custom order below'],['reverse','Reverse all pages'],['odd-first','Odd pages, then even pages'],['even-first','Even pages, then odd pages']])+textField('Custom page order','order','','Unlisted pages are omitted. No duplicate page numbers.','placeholder="3, 1, 2"');
 if(id==='extract')html=range()+s('Output grouping','extractMode',[['combined','All selected pages in one PDF'],['each','One PDF per selected page · ZIP']])+s('Selected page order','selectedOrder',[['normal','Use selected order'],['reverse','Reverse selected order']]);
 if(id==='remove')html=range();
 if(id==='crop')html=s('Crop action','cropMode',[['trim','Trim margins'],['reset','Restore the media-box view · Not redaction']])+s('Margin unit','cropUnit',[['mm','Millimeters'],['pt','Points'],['in','Inches']])+['left','right','top','bottom'].map(side=>n(side[0].toUpperCase()+side.slice(1)+' margin',side,10,0,254)).join('')+range();
 if(id==='resize')html=papers()+n('Page margin (pt)','margin',24,0,144)+s('Content fitting','fitMode',[['contain','Fit entire page'],['cover','Fill · May crop content'],['stretch','Stretch · May distort']])+range();
 if(id==='duplicate')html=n('Additional copies per selected page','copies',1,1,20)+s('Insert copies','insertCopies',[['after','Immediately after each original'],['before','Immediately before each original'],['end','At the end of the document']])+range();
 if(id==='numbers')html=n('Start numbering at','start',1,1,100000)+s('Number format','numberTemplate',[['n','1, 2, 3…'],['page','Page 1'],['fraction','1 / 10'],['page-total','Page 1 of 10'],['custom','Custom template']])+s('Numeral style','numeralStyle',[['decimal','Decimal'],['roman','Roman · I, II, III'],['roman-lower','Roman · i, ii, iii']])+s('Position','position',[['center','Bottom center'],['left','Bottom left'],['right','Bottom right'],['top-center','Top center'],['top-left','Top left'],['top-right','Top right']])+range()+advanced(textField('Custom template','numberCustom','{n} / {total}','Use {n} for number and {total} for last number. ASCII text only.','maxlength="100"')+n('Font size (pt)','fontSize',11,6,72)+s('Number font','numberFont',[['Helvetica','Helvetica'],['TimesRoman','Times Roman'],['Courier','Courier']])+color('Number color','numberColor','#4d4d5c')+n('Edge offset (pt)','numberMargin',24,6,100));
 if(id==='watermark')html=textField('Watermark text','watermark','CONFIDENTIAL','','maxlength="100"')+s('Direction','direction',[['diagonal','Diagonal · 35°'],['horizontal','Horizontal'],['vertical','Vertical · 90°'],['custom','Custom angle']])+n('Opacity (%)','watermarkOpacity',25,1,100)+color('Text color','color','#786a9a')+range()+advanced(n('Custom angle (degrees)','watermarkAngle',35,-180,180)+n('Stamp width (% of page)','stampWidth',72,10,100)+s('Position','stampPosition',[['center','Center'],['top-left','Top left'],['top-right','Top right'],['bottom-left','Bottom left'],['bottom-right','Bottom right']])+s('Stamp pattern','stampPattern',[['single','Single watermark'],['grid','Repeated · 3 × 3']])+s('Font family','stampFont',[['Arial','Arial'],['serif','Serif'],['monospace','Monospace']])+s('Font weight','stampWeight',[['bold','Bold'],['normal','Regular']]));
 if(['text','to-html','to-markdown'].includes(id))html=s('Save as','textFormat',id==='to-html'?[['html','HTML · Web document'],...textFormats.filter(([f])=>f!=='html')]:id==='to-markdown'?[['md','Markdown'],...textFormats.filter(([f])=>f!=='md')]:textFormats)+cleanup()+range()+advanced(txtAdvanced());
 if(id==='to-word')html=s('Save as','wordFormat',[['docx','DOCX · Editable Word or page images'],['rtf','RTF · Text only'],['odt','ODT · Text only'],['txt','TXT · Text only']])+s('DOCX conversion mode','wordMode',[['clean','Clean editable paragraphs'],['layout','Keep lines and font hints'],['appearance','Preserve appearance · Page images, not editable']])+range()+advanced(s('DOCX font','wordFont',[['original','Keep detected font sizes; Arial fallback'],['Arial','Arial'],['Calibri','Calibri'],['Times New Roman','Times New Roman']])+n('Override font size (pt; 0 = detected)','wordSize',0,0,36)+n('Line spacing','wordSpacing',1.1,1,2)+s('DOCX page boundaries','wordBreaks',[['keep','Keep source page boundaries'],['flow','Continuous editable text']])+n('Appearance mode render DPI','wordDpi',144,72,300));
 if(id==='from-word')html=papers()+n('Page margin (pt)','margin',36,12,100)+n('Text size (pt)','docxFontSize',12,8,30)+s('Font family','docxFont',[['Arial','Arial'],['serif','Serif'],['monospace','Monospace']])+n('Line spacing','docxSpacing',1.4,1,2.5)+color('Text color','docxColor','#252b43');
 if(['image-ocr','pdf-ocr'].includes(id))html=s('Text language','language',[['eng','English'],['urd','Urdu'],['ara','Arabic'],['eng+urd','English + Urdu'],['eng+ara','English + Arabic'],['urd+ara','Urdu + Arabic'],['eng+urd+ara','English + Urdu + Arabic']])+s('Save as','output',textFormats)+s('Page layout','segmentation',[['auto','Automatic'],['column','Single column'],['block','Single block'],['line','Single text line'],['sparse','Sparse text']])+cleanup()+(id==='pdf-ocr'?range():'')+advanced(s('Rotate input clockwise','ocrRotation',[['0','No rotation'],['90','90°'],['180','180°'],['270','270°']])+s('Image preparation','ocrColor',[['color','Original colors'],['grayscale','Grayscale'],['bw','Black and white']])+n('Threshold','threshold',128,0,255)+n('Contrast adjustment','contrast',0,-100,100)+s('OCR render DPI · PDFs','ocrDpi',[['180','180 DPI'],['144','144 DPI'],['216','216 DPI'],['300','300 DPI · Memory capped']])+s('Recognize characters','characterMode',[['all','All characters'],['digits','Numbers and punctuation only'],['custom','Custom allowed characters']])+textField('Allowed characters · Custom mode','whitelist','','','maxlength="200"')+txtAdvanced());
 if(id==='metadata')html=s('Document properties','metadataMode',[['edit','Edit properties'],['remove','Clear common properties and XMP']])+['title','author','subject','keywords','creator','producer'].map(k=>textField(k[0].toUpperCase()+k.slice(1),k)).join('')+s('XMP when editing','xmpMode',[['keep','Keep existing XMP'],['remove','Remove existing XMP to avoid stale fields']]);
 if(id==='flatten')html=s('Field appearance handling','fieldAppearance',[['existing','Keep existing appearances'],['regenerate','Regenerate appearances · Standard font support only']])+'<p class="settings-help">All fields are flattened. Regeneration can fail for non-Latin field values; use existing appearances if that happens.</p>';
 if(['add-text','signature'].includes(id)){
  html=id==='add-text'?textField('Text to add','overlayText','','Single-line overlay, up to 160 characters.','maxlength="160"'):s('Signature style','signatureMode',[['draw','Hand-drawn signature'],['typed','Typed visual signature']])+textField('Typed signature name','signatureName','','Used only in typed mode.','maxlength="80"')+'<div class="field"><label for="signature-canvas">Draw your signature</label><canvas id="signature-canvas" width="1000" height="300" aria-label="Signature drawing area"></canvas><button class="text-button" id="clear-signature" type="button">Clear drawing</button></div>';
  html+=n('Left position (%)','x',10,0,90)+n('Top position (%)','y',id==='signature'?75:10,0,90)+n('Width (% of page)','width',id==='signature'?35:70,10,100)+range()+advanced(color('Ink / text color','color','#252b43')+n('Opacity (%)','overlayOpacity',100,1,100)+n('Rotation (degrees)','overlayAngle',0,-180,180)+(id==='signature'?n('Drawing stroke width','strokeWidth',4,1,15):s('Font family','overlayFont',[['Arial','Arial'],['serif','Serif'],['monospace','Monospace']])+s('Font style','overlayStyle',[['normal','Regular'],['bold','Bold'],['italic','Italic'],['bold italic','Bold italic']])));
 }
 return html+'<details class="advanced-options"><summary>Download filename</summary><div>'+textField('Output filename (optional)','outputName','','Use a base name; the correct extension is added automatically.','maxlength="100"')+'</div></details>';
}

export const expandedNotes={
 'to-images':'Pages are rendered, not original image extraction. DPI and long-edge settings are targets capped to 12 megapixels. GIF is a single-frame 256-color image; SVG embeds PNG; ICO is a thumbnail. TIFF, BMP and PPM are uncompressed. Transparency applies to PNG, WebP and SVG only. An operation is limited to 50 selected pages and 180 MB output.',
 images:'One decoded frame per image becomes a PDF page. GIF uses one frame; AVIF and ICO decoding depend on your browser. Image resolution is capped at 4,000 px on the long edge. Fill mode may crop and stretch mode may distort. Background color fills transparent areas.',
 split:'Choose individual pages, custom ranges, groups of N pages, or odd/even groups. Up to 100 output PDFs; multiple parts are packaged in a ZIP.',
 merge:'Merge manually ordered or filename-sorted documents, optionally filtering odd/even pages and adding blank separators. Up to 500 output pages including separators. Forms and signatures may change.',
 organize:'Use a custom order, reverse the document or group odd/even pages. Custom order omits pages not listed and rejects duplicates.',
 rotate:'Relative mode adds to existing rotation. Absolute mode sets the chosen orientation, including a 0° reset. Page selection supports custom, odd/even, first or last.',
 text:'Text-only export in eight formats. Scans need the separate OCR tool. CSV escapes potential spreadsheet formulas by prefixing an apostrophe. Original images, tables and layout are not retained.',
 'to-html':'HTML is escaped and text only. You can choose other text output formats, page headings, and cleanup. Encoding and line-ending controls affect TXT, CSV and Markdown only.',
 'to-markdown':'Markdown escapes text markup; it does not reconstruct source tables. Other text outputs are available. Encoding and line-ending controls affect TXT, CSV and Markdown only.',
 'to-word':'DOCX supports editable paragraphs, approximate line formatting, or page images. RTF, ODT and TXT are text-only exports and require an editable mode. Font, spacing and page-boundary controls apply to editable DOCX. Complex layouts can differ.',
 crop:'Choose trim units in mm, points or inches, or restore the media-box view. Hidden content remains recoverable; this is not redaction. Very large margins are rejected.',
 resize:'Choose standard or custom paper, orientation, margins and fit behavior. Fill can crop content; stretch can distort. Forms, links and rotation behavior may change.',
 duplicate:'Copies can be placed before or after each original or appended at the end. Up to 20 additional copies per selection, with a 500-page output limit.',
 signature:'Draw a signature or type a visual signature name. Typed output uses device cursive fonts. Color and stroke changes affect new drawing strokes. This is not certificate-based signing or identity verification.',
 'image-ocr':'Up to 10 images. Choose bundled English, Urdu and Arabic models or combinations, recognition layout and image preparation. Review all text; Nastaleeq, handwriting and scans can be inaccurate. Text outputs do not preserve page layout.',
 'pdf-ocr':'Up to 10 selected PDF pages. DPI is capped for device memory. Choose language combinations and review recognized text before saving. Output is text, not a searchable PDF or a faithful document layout.',
 numbers:'Number selected pages with decimal or Roman numerals, templates, font, color and placement. {total} is the last number in this numbered sequence. Custom templates use ASCII text. Roman values are limited to 1–3999.'
};
